\begin{proposition}
Let $p>2$ be a prime and let $a$ be a nonnegative integer. Then
\[
\sum_{m_1=0}^{p^a-1}\sum_{m_2=0}^{p^a-1}\sum_{m_3=0}^{p^a-1}
\frac{(m_1+m_2+m_3)!}{m_1!m_2!m_3!}
\equiv 1\pmod p.
\]
\end{proposition}

